"use client"

import React, { useState } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { Search, Award, School, Globe, User, FileText, Loader2 } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { ElegantBackground } from '@/components/ui/elegant-background'
import { searchCertificate, Certificate } from './actions'

export default function CertificatePortal() {
  const [query, setQuery] = useState('')
  const [results, setResults] = useState<Certificate[]>([])
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  const [hasSearched, setHasSearched] = useState(false)

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!query.trim()) return

    setLoading(true)
    setError('')
    setResults([])
    setHasSearched(true)

    try {
      const response = await searchCertificate(query.trim())
      if (response.success && response.data) {
        setResults(response.data)
      } else {
        setError(response.error || 'No certificates found')
      }
    } catch (err) {
      setError('An error occurred while searching')
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="min-h-screen relative overflow-hidden">
      <ElegantBackground variant="section" />
      
      <div className="relative z-10 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-24">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6 }}
          className="text-center mb-12"
        >
          <h1 className="font-display text-4xl md:text-5xl font-bold text-foreground mb-4">
            Certificate <span className="text-accent-gold">Portal</span>
          </h1>
          <p className="text-lg text-muted-foreground max-w-2xl mx-auto">
            Verify and view IGACMUN certificates. Enter your Certificate ID or Name below.
          </p>
        </motion.div>

        {/* Search Section */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6, delay: 0.2 }}
          className="max-w-2xl mx-auto mb-16"
        >
          <form onSubmit={handleSearch} className="relative flex items-center">
            <div className="relative w-full group">
              <div className="absolute inset-0 bg-accent-gold/20 rounded-lg blur-md group-hover:blur-lg transition-all duration-300 opacity-50" />
              <input
                type="text"
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                placeholder="Enter Certificate ID or Name..."
                className="w-full bg-forest-900/80 border border-accent-gold/30 text-foreground placeholder:text-muted-foreground/50 rounded-lg py-4 pl-12 pr-32 focus:outline-none focus:border-accent-gold/60 focus:ring-1 focus:ring-accent-gold/60 transition-all backdrop-blur-sm relative z-10"
              />
              <Search className="absolute left-4 top-1/2 transform -translate-y-1/2 text-accent-gold/70 h-5 w-5 z-20" />
              
              <div className="absolute right-2 top-1/2 transform -translate-y-1/2 z-20">
                <Button 
                  type="submit" 
                  disabled={loading}
                  className="bg-accent-gold/10 hover:bg-accent-gold/20 text-accent-gold border border-accent-gold/30"
                >
                  {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : 'Search'}
                </Button>
              </div>
            </div>
          </form>
        </motion.div>

        {/* Results Section */}
        <div className="max-w-5xl mx-auto">
          <AnimatePresence mode="wait">
            {loading ? (
              <motion.div
                key="loading"
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                className="flex justify-center py-12"
              >
                <div className="flex flex-col items-center gap-4">
                  <div className="relative">
                    <div className="w-12 h-12 border-4 border-accent-gold/20 border-t-accent-gold rounded-full animate-spin" />
                    <div className="absolute inset-0 flex items-center justify-center">
                      <div className="w-2 h-2 bg-accent-gold rounded-full animate-pulse" />
                    </div>
                  </div>
                  <p className="text-accent-gold/70 font-medium animate-pulse">Searching Database...</p>
                </div>
              </motion.div>
            ) : error ? (
              <motion.div
                key="error"
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0 }}
                className="text-center py-12"
              >
                <div className="bg-destructive/10 border border-destructive/30 rounded-lg p-6 max-w-md mx-auto">
                  <p className="text-destructive font-medium">{error}</p>
                </div>
              </motion.div>
            ) : results.length > 0 ? (
              <motion.div
                key="results"
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                className="grid grid-cols-1 md:grid-cols-2 gap-6"
              >
                {results.map((cert, index) => (
                  <motion.div
                    key={cert.id}
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ duration: 0.5, delay: index * 0.1 }}
                    className="group relative"
                  >
                    <div className="absolute inset-0 bg-gradient-to-br from-accent-gold/10 to-transparent rounded-xl blur-sm opacity-0 group-hover:opacity-100 transition-opacity duration-500" />
                    
                    <div className="relative bg-forest-900/40 border border-accent-gold/20 rounded-xl p-6 md:p-8 backdrop-blur-md hover:border-accent-gold/40 transition-all duration-300 overflow-hidden">
                      {/* Decorative background elements */}
                      <div className="absolute top-0 right-0 w-32 h-32 bg-accent-gold/5 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2" />
                      
                      <div className="relative z-10">
                        <div className="flex items-start justify-between mb-6">
                          <div className="p-3 bg-accent-gold/10 rounded-lg border border-accent-gold/20">
                            <Award className="h-8 w-8 text-accent-gold" />
                          </div>
                          <div className="text-right">
                            <p className="text-xs text-muted-foreground uppercase tracking-wider mb-1">Certificate ID</p>
                            <p className="font-mono text-sm text-accent-gold">{cert.id.slice(0, 8)}...</p>
                          </div>
                        </div>

                        <div className="space-y-4">
                          <div>
                            <h3 className="font-display text-2xl font-bold text-white mb-1">{cert.name}</h3>
                            <div className="flex items-center gap-2 text-muted-foreground">
                              <School className="h-4 w-4" />
                              <span className="text-sm">{cert.school}</span>
                            </div>
                          </div>

                          <div className="h-px w-full bg-gradient-to-r from-accent-gold/30 to-transparent" />

                          <div className="grid grid-cols-2 gap-4">
                            <div>
                              <p className="text-xs text-muted-foreground mb-1 flex items-center gap-1">
                                <FileText className="h-3 w-3" /> Type
                              </p>
                              <p className="text-sm font-medium text-foreground">{cert.certificate_type}</p>
                            </div>
                            <div>
                              <p className="text-xs text-muted-foreground mb-1 flex items-center gap-1">
                                <User className="h-3 w-3" /> Committee
                              </p>
                              <p className="text-sm font-medium text-foreground">{cert.committee}</p>
                            </div>
                            <div className="col-span-2">
                              <p className="text-xs text-muted-foreground mb-1 flex items-center gap-1">
                                <Globe className="h-3 w-3" /> Country/Portfolio
                              </p>
                              <p className="text-sm font-medium text-foreground">{cert.country}</p>
                            </div>
                          </div>
                        </div>

                        <div className="mt-6 pt-4 border-t border-white/5 flex justify-between items-center">
                          <span className="text-xs text-muted-foreground">
                            Issued on {new Date(cert.created_at).toLocaleDateString()}
                          </span>
                          <div className="flex gap-2">
                            <Button variant="ghost" size="sm" className="text-xs hover:text-accent-gold hover:bg-accent-gold/10">
                              Download PDF
                            </Button>
                          </div>
                        </div>
                      </div>
                    </div>
                  </motion.div>
                ))}
              </motion.div>
            ) : hasSearched ? (
              <motion.div
                key="empty"
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                className="text-center py-12"
              >
                <p className="text-muted-foreground">No certificates found matching your query.</p>
              </motion.div>
            ) : null}
          </AnimatePresence>
        </div>
      </div>
    </div>
  )
}
